    }
    public static function retry(int $publicationId):array{$p=self::row($publicationId);if((string)$p['state']!=='failed')throw new RuntimeException('social_publication_not_failed');db()->prepare("UPDATE social_publications SET state='queued',job_id=NULL,error_code=NULL,provider_response_json=NULL,updated_at=NOW() WHERE id=?")->execute([$publicationId]);return ['publication_id'=>$publicationId,'job_id'=>self::enqueue($publicationId,90)];}
    public static function publishNow(int $publicationId):array{$p=self::row($publicationId);if((string)$p['state']==='failed')db()->prepare("UPDATE social_publications SET state='queued',job_id=NULL,error_code=NULL,updated_at=NOW() WHERE id=?")->execute([$publicationId]);elseif((string)$p['state']!=='queued')throw new RuntimeException('social_publication_not_queueable');return ['publication_id'=>$publicationId,'job_id'=>self::enqueue($publicationId,95)];}

