        $published=$state==='published';db()->prepare("UPDATE social_publications SET state=?,external_post_id=?,external_url=?,provider_response_json=?,error_code=?,published_at=IF(?,NOW(),published_at),last_checked_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$state,$externalId?:null,$url?:null,$response?j($response):null,$error?:null,$published?1:0,$id]);$p=self::row($id);if($published)db()->prepare("UPDATE social_content SET status='published',updated_at=NOW() WHERE id=?")->execute([(int)$p['content_id']]);elseif($state==='failed')db()->prepare("UPDATE social_content SET status=IF(status='published','published','failed'),updated_at=NOW() WHERE id=?")->execute([(int)$p['content_id']]);else db()->prepare("UPDATE social_content SET status='publishing',updated_at=NOW() WHERE id=? AND status<>'published'")->execute([(int)$p['content_id']]);
