                $chat=$externalRef?:TelegramClient::defaultChatId();$asset=self::asset($assetId?:null);$url=$assetId?self::assetUrl($assetId):'';if($asset&&$url!==''&&(string)$asset['asset_type']==='video')$r=TelegramClient::sendVideoUrl($chat,$url,$caption?:$title);else$r=TelegramClient::sendMessage($chat,$caption?:$title);$mid=(string)($r['result']['message_id']??'');self::finalize($id,'published',$mid,'',$r);return ['publication_id'=>$id,'state'=>'published','message_id'=>$mid];
            }
